-- ─── Hand-written integrity rules (not expressible in Prisma) ────────────────

ALTER TABLE "risk_model_config" ADD CONSTRAINT "risk_model_config_version_check" CHECK ("version" >= 1);
-- At most one active weights version per tenant.
CREATE UNIQUE INDEX "risk_model_config_one_active" ON "risk_model_config" ("tenant_id") WHERE "is_active";

ALTER TABLE "risk_score" ADD CONSTRAINT "risk_score_score_check" CHECK ("score" >= 0 AND "score" <= 100);
ALTER TABLE "risk_score" ADD CONSTRAINT "risk_score_factors_array" CHECK (jsonb_typeof("factors") = 'array');

ALTER TABLE "track_assignment" ADD CONSTRAINT "track_assignment_confidence_check" CHECK ("confidence" >= 0 AND "confidence" <= 1);
ALTER TABLE "track_assignment" ADD CONSTRAINT "track_assignment_review_after_effective"
  CHECK ("review_date" IS NULL OR "review_date" >= "effective_date");
-- One active track per student.
CREATE UNIQUE INDEX "track_assignment_one_active" ON "track_assignment" ("tenant_id", "student_person_id")
  WHERE "status" = 'active';

ALTER TABLE "action_card" ADD CONSTRAINT "action_card_confidence_check" CHECK ("confidence" >= 0 AND "confidence" <= 1);
-- A decided card records who decided and when; an edited card records what was applied.
ALTER TABLE "action_card" ADD CONSTRAINT "action_card_decision_recorded"
  CHECK ("status" NOT IN ('approved', 'edited', 'dismissed') OR "decided_at" IS NOT NULL);
ALTER TABLE "action_card" ADD CONSTRAINT "action_card_edited_payload"
  CHECK ("status" <> 'edited' OR "decided_payload" IS NOT NULL);

ALTER TABLE "alert_rule" ADD CONSTRAINT "alert_rule_escalation_array"
  CHECK (jsonb_typeof("escalation") = 'array' AND jsonb_array_length("escalation") >= 1);

ALTER TABLE "alert" ADD CONSTRAINT "alert_escalation_level_check" CHECK ("escalation_level" >= 0);
ALTER TABLE "alert" ADD CONSTRAINT "alert_acknowledgements_array" CHECK (jsonb_typeof("acknowledgements") = 'array');
-- At most one unresolved alert per rule x student (re-triggering updates it instead).
CREATE UNIQUE INDEX "alert_one_unresolved" ON "alert" ("tenant_id", "rule_id", "student_person_id")
  WHERE "state" IN ('open', 'acknowledged', 'escalated');

ALTER TABLE "intervention" ADD CONSTRAINT "intervention_risk_range"
  CHECK (("risk_before" IS NULL OR "risk_before" BETWEEN 0 AND 100) AND ("risk_after" IS NULL OR "risk_after" BETWEEN 0 AND 100));
ALTER TABLE "intervention" ADD CONSTRAINT "intervention_dates_order"
  CHECK ("ended_on" IS NULL OR "started_on" IS NULL OR "ended_on" >= "started_on");

ALTER TABLE "goal_progress" ADD CONSTRAINT "goal_progress_pct_check" CHECK ("progress_pct" >= 0 AND "progress_pct" <= 100);

-- week_start is the Monday of its ISO week, so (goal, week_start) really means one nudge per week.
ALTER TABLE "nudge" ADD CONSTRAINT "nudge_week_start_monday" CHECK (EXTRACT(ISODOW FROM "week_start") = 1);
